                    sh:datatype xsd:string ;
                    sh:maxCount 1 ;
                    sh:message "schema:dateModified is required (ISO 8601 date string)." ;
                    sh:minCount 1 ;
                    sh:path schema1:dateModified ] ],
        [ a sh:ValidationResult ;
